def exterior(left, right):
    merged = []
    i = 0
    j = 0
    sign = 1
    while i < len(left) and j < len(right):
        if left[i] == right[j]:
            return (), 0
        if left[i] < right[j]:
            merged.append(left[i])
            i += 1
        else:
            merged.append(right[j])
            sign *= 1 - 2 * ((len(left) - i) % 2)
            j += 1
    merged.extend(left[i:])
    merged.extend(right[j:])
    return tuple(merged), sign


def crossing(annihilators, creators, cache):
    matches = tuple(annihilators.index(mode) if mode in annihilators else -1 for mode in creators)
    key = (len(annihilators), matches)
    states = cache.get(key, ())
    if not states:
        states = [((), tuple(range(len(annihilators))), 1)]
        for position, match in enumerate(matches):
            following = []
            for kept, remaining, coefficient in states:
                following.append((kept + (position,), remaining, coefficient * (1 - 2 * (len(remaining) % 2))))
                if match in remaining:
                    location = remaining.index(match)
                    sign = 1 - 2 * ((len(remaining) - location - 1) % 2)
                    following.append((kept, remaining[:location] + remaining[location + 1:], coefficient * sign))
            states = following
        cache[key] = states
    return states


def multiply(left, right, cache):
    left_creators, left_annihilators = left
    right_creators, right_annihilators = right
    terms = []
    for kept, remaining, coefficient in crossing(left_annihilators, right_creators, cache):
        creators, creation_sign = exterior(left_creators, tuple(right_creators[k] for k in kept))
        if creation_sign:
            annihilators, annihilation_sign = exterior(tuple(left_annihilators[k] for k in remaining), right_annihilators)
            if annihilation_sign:
                terms.append(((creators, annihilators), coefficient * creation_sign * annihilation_sign))
    return terms


def normalize(word, cache):
    polynomial = {((), ()): 1}
    for creation, mode in word:
        operator = ((mode,), ()) if creation else ((), (mode,))
        following = {}
        for monomial, coefficient in polynomial.items():
            for product, factor in multiply(monomial, operator, cache):
                following[product] = following.get(product, 0) + coefficient * factor
        polynomial = {monomial: coefficient for monomial, coefficient in following.items() if coefficient}
    return polynomial


def propose(payload):
    words = payload["words"]
    kernels = {}
    basis = []
    adjoints = []
    for word in words:
        polynomial = normalize(word, kernels)
        basis.append(list(polynomial.items()))
        adjoint = []
        for monomial, coefficient in polynomial.items():
            creators, annihilators = monomial
            nc = len(creators)
            na = len(annihilators)
            reversals = nc * (nc - 1) // 2 + na * (na - 1) // 2
            sign = 1 - 2 * (reversals % 2)
            adjoint.append(((annihilators, creators), coefficient * sign))
        adjoints.append(adjoint)
    result = {}
    canonical_words = {}
    for i in range(len(words)):
        if adjoints[i]:
            for j in range(i, len(words)):
                if basis[j]:
                    polynomial = {}
                    for left, left_coefficient in adjoints[i]:
                        for right, right_coefficient in basis[j]:
                            scale = left_coefficient * right_coefficient
                            for monomial, coefficient in multiply(left, right, kernels):
                                polynomial[monomial] = polynomial.get(monomial, 0) + scale * coefficient
                    if i != j:
                        for monomial, coefficient in list(polynomial.items()):
                            creators, annihilators = monomial
                            transpose = (annihilators, creators)
                            polynomial[transpose] = polynomial.get(transpose, 0) + coefficient
                    coordinate = (i, j)
                    for monomial, coefficient in polynomial.items():
                        if coefficient:
                            if monomial not in canonical_words:
                                creators, annihilators = monomial
                                canonical_words[monomial] = tuple((1, mode) for mode in creators) + tuple((0, mode) for mode in annihilators)
                            canonical = canonical_words[monomial]
                            result.setdefault(canonical, {})[coordinate] = coefficient
    return result

def wedge(left, right):
    merged = []
    i = 0
    j = 0
    crossings = 0
    while i < len(left) and j < len(right):
        if left[i] == right[j]:
            return (), 0
        if left[i] < right[j]:
            merged.append(left[i])
            i += 1
        else:
            merged.append(right[j])
            crossings += len(left) - i
            j += 1
    merged.extend(left[i:])
    merged.extend(right[j:])
    return tuple(merged), 1 - 2 * (crossings % 2)


def normalize(word):
    states = {((), ()): 1}
    for flag, mode in word:
        following = {}
        for groups, coefficient in states.items():
            creators, annihilators = groups
            if flag == 0:
                merged, sign = wedge(annihilators, (mode,))
                if sign:
                    target = (creators, merged)
                    following[target] = following.get(target, 0) + coefficient * sign
            else:
                if mode in annihilators:
                    position = annihilators.index(mode)
                    sign = 1 - 2 * ((len(annihilators) - 1 - position) % 2)
                    remaining = annihilators[:position] + annihilators[position + 1:]
                    target = (creators, remaining)
                    following[target] = following.get(target, 0) + coefficient * sign
                merged, sign = wedge(creators, (mode,))
                if sign:
                    sign *= 1 - 2 * (len(annihilators) % 2)
                    target = (merged, annihilators)
                    following[target] = following.get(target, 0) + coefficient * sign
        states = {groups: coefficient for groups, coefficient in following.items() if coefficient}
        if not states:
            break
    return states


def expand(leftc, lefta, rightc, righta):
    if any(mode in rightc and mode not in lefta for mode in leftc):
        return []
    if any(mode in righta and mode not in rightc for mode in lefta):
        return []
    size = len(rightc)
    exponent = len(lefta) * size
    exponent += sum(1 for a in leftc for b in rightc if a > b)
    exponent += sum(1 for a in lefta for b in righta if a > b)
    required = []
    optional = []
    for position, mode in enumerate(lefta):
        if mode in rightc:
            correction = rightc.index(mode) - position - size
            correction -= sum(1 for other in leftc if other > mode)
            correction -= sum(1 for other in righta if other < mode)
            if mode in leftc or mode in righta:
                required.append(mode)
                exponent += correction
            else:
                optional.append((mode, correction))
    count = len(required)
    exponent += count * (count - 1) // 2
    creators = tuple(sorted(leftc + tuple(mode for mode in rightc if mode not in required)))
    annihilators = tuple(sorted(tuple(mode for mode in lefta if mode not in required) + righta))
    states = [(creators, annihilators, 1 - 2 * (exponent % 2), count)]
    for mode, correction in optional:
        following = states.copy()
        for creators, annihilators, coefficient, count in states:
            remainingc = tuple(other for other in creators if other != mode)
            remaininga = tuple(other for other in annihilators if other != mode)
            sign = 1 - 2 * ((correction + count) % 2)
            following.append((remainingc, remaininga, coefficient * sign, count + 1))
        states = following
    return states


def propose(payload):
    words = payload['words']
    normalized = {}
    forms = []
    adjoints = []
    for word in words:
        if word not in normalized:
            polynomial = normalize(word)
            terms = []
            dual = []
            for groups, coefficient in polynomial.items():
                creators, annihilators = groups
                terms.append((creators, annihilators, coefficient))
                p = len(creators)
                q = len(annihilators)
                exponent = p * (p - 1) // 2 + q * (q - 1) // 2
                sign = 1 - 2 * (exponent % 2)
                dual.append((annihilators, creators, coefficient * sign))
            normalized[word] = (tuple(terms), tuple(dual))
        terms, dual = normalized[word]
        forms.append(terms)
        adjoints.append(dual)
    rows = {}
    for i in range(len(words)):
        if not adjoints[i]:
            continue
        for j in range(i, len(words)):
            if not forms[j]:
                continue
            coordinate = (i, j)
            for leftc, lefta, leftcoef in adjoints[i]:
                for rightc, righta, rightcoef in forms[j]:
                    factor = leftcoef * rightcoef
                    for creators, annihilators, coefficient, count in expand(leftc, lefta, rightc, righta):
                        value = factor * coefficient
                        groups = (creators, annihilators)
                        row = rows.setdefault(groups, {})
                        row[coordinate] = row.get(coordinate, 0) + value
                        if i != j:
                            groups = (annihilators, creators)
                            row = rows.setdefault(groups, {})
                            row[coordinate] = row.get(coordinate, 0) + value
    result = {}
    for groups, coordinates in rows.items():
        entries = {coordinate: coefficient for coordinate, coefficient in coordinates.items() if coefficient}
        if entries:
            creators, annihilators = groups
            word = tuple((1, mode) for mode in creators) + tuple((0, mode) for mode in annihilators)
            result[word] = entries
    return result

